import { useId, type ComponentProps, type ElementType, type ReactNode } from "react";

import { SegmentedControl } from "@rhs-ui/application/segmented-control";
import { IconArrowDown, IconArrowUp, IconPackage, IconStar } from "@rhs-ui/icons";
import { AnimatedPrice } from "@rhs-ui/commerce/animated-price";
import { RankedAddButton } from "@rhs-ui/commerce/ranked-product-list/add-button";
import {
  DEFAULT_PERIODS,
  WORDS,
  fill,
  movementOf,
  type RankedMovement,
  type RankedPeriod,
  type RankedProduct,
  type RankedProductImage,
  type RankedProductListLabels,
} from "@rhs-ui/commerce/ranked-product-list/ranking";
import { Badge } from "@rhs-ui/primitives/badge";
import { cn } from "@/lib/utils";

export type { RankedMovement, RankedPeriod, RankedProduct, RankedProductImage, RankedProductListLabels } from "@rhs-ui/commerce/ranked-product-list/ranking";

export interface RankedProductListProps extends Omit<ComponentProps<"section">, "children" | "title"> {
  /** The best sellers, best first. A product's rank is its place in the array. */
  items: readonly RankedProduct[];
  /** The period the list shows: the `value` of one of `periods`. The list is controlled, so it shows what you pass for this period. */
  period: string;
  /** The periods to choose from. Defaults to this week, this month and all time. */
  periods?: readonly RankedPeriod[];
  /** Called with the value of the period that was chosen. Fetch or pick the list for it and pass it back as `items` and `period`. Without it the periods are not offered and the list just says which one it shows. */
  onPeriodChange?: (period: string) => void;
  /** Called when a row's Add button is pressed. Return a promise and the button shows it is working; reject it and the button says "Try again" and a screen reader is told. Without it the buttons are left out. */
  onAddToCart?: (item: RankedProduct) => void | Promise<void>;
  /** How many places to show. Without it every product is shown. */
  limit?: number;
  /** Renders the links of the rows. Defaults to "a"; pass your router's Link. */
  linkAs?: ElementType;
  /** Draws a product picture: plug in next/image or any optimiser. Defaults to a plain <img>. */
  renderImage?: (image: RankedProductImage, className: string) => ReactNode;
  /** ISO 4217 code for the prices. */
  currency?: string;
  /** Always pass your application locale, so the server and the browser write the same prices and numbers. */
  locale?: string;
  /** The heading. Defaults to "Best sellers". */
  title?: string;
  /** The line under it. */
  description?: string;
  /** The heading's element: "h2" by default, "h3" inside a section that has its own h2. The names of the products sit one level below. */
  headingAs?: "h2" | "h3";
  /** The words, for another language. */
  labels?: RankedProductListLabels;
}

function DefaultImage(image: RankedProductImage, className: string) {
  // eslint-disable-next-line @next/next/no-img-element -- framework-neutral default; pass renderImage to use next/image
  return <img src={image.src} alt={image.alt ?? ""} width={image.width} height={image.height} loading="lazy" decoding="async" className={className} />;
}

/** The movement as a small chip: always the word, with an arrow where there is a direction. `decorative` hides a second copy from screen readers, which hear it once, after the name. */
function Movement({ movement, numbers, words, className, decorative }: { movement: RankedMovement | undefined; numbers: Intl.NumberFormat; words: typeof WORDS; className?: string; decorative?: boolean }) {
  const found = movementOf(movement, numbers, words);
  if (!found) return null;
  return (
    <Badge
      data-movement={found.kind}
      aria-hidden={decorative || undefined}
      variant={found.kind === "new" ? "default" : found.kind === "same" ? "muted" : "outline"}
      className={cn("shrink-0 tabular-nums", className)}
    >
      {found.kind === "up" ? <IconArrowUp aria-hidden="true" /> : found.kind === "down" ? <IconArrowDown aria-hidden="true" /> : null}
      {found.text}
    </Badge>
  );
}

/**
 * A best-sellers list people can scan in five seconds: each place has a large rank figure, a picture, the name, the
 * price, a line of proof ("1,240 sold this week", or a rating) and a word for how it moved ("New", "Up 2", "Down 1"),
 * which is always a word as well as an arrow. A control switches the period and tells you when it changed, and the
 * list announces the new period politely. Each row is one link with its own Add button on top. On a wide screen the
 * proof has a column of its own; on a phone the picture shrinks and the proof moves under the name. The list is
 * controlled: you hold the period and pass the products that belong to it.
 */
export function RankedProductList({
  items,
  period,
  periods = DEFAULT_PERIODS,
  onPeriodChange,
  onAddToCart,
  limit,
  linkAs: Link = "a",
  renderImage = DefaultImage,
  currency = "EUR",
  locale = "en-US",
  title,
  description,
  headingAs: Heading = "h2",
  labels,
  className,
  ...props
}: RankedProductListProps) {
  const words = { ...WORDS, ...labels };
  const id = useId();
  const Item = Heading === "h2" ? "h3" : "h4";
  const numbers = new Intl.NumberFormat(locale);
  const money = new Intl.NumberFormat(locale, { style: "currency", currency });
  const shown = limit === undefined ? items : items.slice(0, Math.max(0, Math.floor(limit)));
  const periodLabel = periods.find((entry) => entry.value === period)?.label ?? period;
  const choices = onPeriodChange && periods.length > 1;

  return (
    <section data-slot="ranked-product-list" aria-labelledby={`${id}-title`} className={cn("@container grid min-w-0 grid-cols-[minmax(0,1fr)] gap-5", className)} {...props}>
      <header className="flex flex-wrap items-end justify-between gap-x-6 gap-y-4">
        <div className="min-w-0">
          <Heading id={`${id}-title`} className="text-xl leading-tight font-medium tracking-[-0.03em] text-balance @3xl:text-2xl">
            {title ?? words.title}
          </Heading>
          <p className="mt-1 text-sm text-muted-foreground">{description ?? words.description}</p>
        </div>
        {choices ? (
          <SegmentedControl
            label={words.period}
            options={periods.map((entry) => ({ value: entry.value, label: entry.label }))}
            value={period}
            onValueChange={onPeriodChange}
            className="@max-sm:w-full @max-sm:[&>button]:flex-1 @max-sm:[&>button]:px-1.5"
          />
        ) : (
          <p className="text-sm font-medium">{periodLabel}</p>
        )}
      </header>

      {shown.length === 0 ? (
        <p className="rounded-xl border border-dashed border-border px-4 py-10 text-center text-sm text-muted-foreground">{words.empty}</p>
      ) : (
        <ol role="list" aria-label={fill(words.list, { period: periodLabel })} className="divide-y divide-border overflow-hidden rounded-xl border border-border bg-card shadow-xs">
          {shown.map((item, index) => {
            const rank = index + 1;
            const available = item.available !== false;
            const hasRating = item.rating !== undefined && Number.isFinite(item.rating);
            const onSale = item.compareAtPrice !== undefined && item.compareAtPrice > item.price;
            return (
              <li
                key={item.id}
                data-slot="ranked-product-list-item"
                data-rank={rank}
                className="relative grid grid-cols-[1.75rem_3rem_minmax(0,1fr)_auto] items-center gap-x-3.5 px-3.5 py-3.5 transition-colors duration-150 hover:bg-muted/40 motion-reduce:transition-none @3xl:grid-cols-[4.75rem_4rem_minmax(0,1fr)_minmax(0,11rem)_6rem_auto] @3xl:gap-x-5 @3xl:px-5 @3xl:py-4"
              >
                {/* The rank, with how it moved under it on a wide list; on a phone the movement sits under the name instead. */}
                <div className="grid justify-items-center gap-1.5">
                  <span
                    aria-hidden="true"
                    className={cn("text-center text-xl leading-none font-medium tracking-[-0.05em] tabular-nums @3xl:text-3xl", rank <= 3 ? "text-foreground" : "text-muted-foreground")}
                  >
                    {numbers.format(rank)}
                  </span>
                  <Movement movement={item.movement} numbers={numbers} words={words} className="hidden @3xl:inline-flex" decorative />
                </div>

                <span aria-hidden="true" className={cn("relative grid size-12 place-items-center overflow-hidden rounded-lg bg-muted @3xl:size-16", !available && "opacity-60 grayscale")}>
                  {item.image ? renderImage(item.image, "size-full object-cover") : <IconPackage className="size-5 text-muted-foreground" />}
                </span>

                <div className="min-w-0 @3xl:contents">
                  <div className="min-w-0 @3xl:col-start-3 @3xl:row-start-1">
                    <div className="flex flex-wrap items-center gap-x-2.5 gap-y-1">
                      <Item className="min-w-0 text-sm leading-snug font-medium text-pretty">
                        <Link
                          href={item.href}
                          className="rounded-sm outline-none after:absolute after:inset-0 focus-visible:after:ring-[3px] focus-visible:after:ring-inset focus-visible:after:ring-ring/50"
                        >
                          <span className="sr-only">{fill(words.rank, { rank: numbers.format(rank) })}: </span>
                          {item.name}
                        </Link>
                      </Item>
                      <Movement movement={item.movement} numbers={numbers} words={words} className="@3xl:sr-only" />
                    </div>
                    {item.subtitle ? <p className="mt-0.5 text-xs text-muted-foreground">{item.subtitle}</p> : null}
                  </div>

                  {item.proof || hasRating ? (
                    <p className="mt-1.5 flex flex-col gap-0.5 text-xs text-muted-foreground @3xl:col-start-4 @3xl:row-start-1 @3xl:mt-0 @3xl:text-sm">
                      {hasRating && item.rating !== undefined ? (
                        <span className="inline-flex items-center gap-1 tabular-nums">
                          <IconStar aria-hidden="true" className="size-3.5 fill-current text-foreground" />
                          <span aria-hidden="true" className="font-medium text-foreground">
                            {new Intl.NumberFormat(locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(item.rating)}
                          </span>
                          {item.ratingCount !== undefined ? <span aria-hidden="true">({numbers.format(item.ratingCount)})</span> : null}
                          <span className="sr-only">
                            {fill(words.ratingName, { rating: new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(item.rating), count: numbers.format(item.ratingCount ?? 0) })}
                          </span>
                        </span>
                      ) : null}
                      {item.proof ? <span>{item.proof}</span> : null}
                    </p>
                  ) : null}

                  <p className="mt-1.5 flex flex-wrap items-baseline gap-x-2 text-sm font-medium tabular-nums @3xl:col-start-5 @3xl:row-start-1 @3xl:mt-0 @3xl:flex-col @3xl:items-end @3xl:gap-x-0">
                    <AnimatedPrice value={item.price / 100} currency={currency} locale={locale} className={cn(onSale && "text-foreground")} />
                    {onSale && item.compareAtPrice !== undefined ? (
                      <>
                        <span className="sr-only">{words.was}</span>
                        <s className="text-xs font-normal text-muted-foreground">{money.format(item.compareAtPrice / 100)}</s>
                      </>
                    ) : null}
                  </p>
                </div>

                {onAddToCart ? (
                  <div className="@3xl:col-start-6 @3xl:row-start-1">
                    <RankedAddButton
                      label={words.add}
                      busyLabel={words.adding}
                      addedLabel={words.added}
                      retryLabel={words.retry}
                      soldOutLabel={words.soldOut}
                      name={fill(available ? words.addName : words.soldOutName, { name: item.name })}
                      addedName={fill(words.addedName, { name: item.name })}
                      failedName={fill(words.failedName, { name: item.name })}
                      soldOut={!available}
                      onAdd={() => onAddToCart(item)}
                    />
                  </div>
                ) : null}
              </li>
            );
          })}
        </ol>
      )}

      <p role="status" className="sr-only">
        {shown.length === 1 ? fill(words.statusOne, { period: periodLabel }) : fill(words.status, { period: periodLabel, count: numbers.format(shown.length) })}
      </p>
    </section>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

import { IconCheck, IconPlus, IconRefresh, IconSpinner } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";

export interface RankedAddButtonProps {
  /** The button's words at rest. */
  label: string;
  /** The word while it works. */
  busyLabel: string;
  /** The word once the product is in the bag. */
  addedLabel: string;
  /** The word for a moment after an add that failed: the button then tries again when it is pressed. */
  retryLabel: string;
  /** The word on a product that cannot be bought. */
  soldOutLabel: string;
  /** What a screen reader hears at rest. For a product that cannot be bought it says so, with the visible words in it. */
  name: string;
  /** What a screen reader hears once the product is in the bag. */
  addedName: string;
  /** What a screen reader hears, and the polite message, after an add that failed. */
  failedName: string;
  /** True for a product that cannot be bought: the button is off and says so. */
  soldOut?: boolean;
  /** Called when the button is pressed. Return a promise and the button shows it is working; reject and it says "Try again" for a few seconds. */
  onAdd?: () => void | Promise<void>;
  /** Extra classes for the button. */
  className?: string;
}

type AddState = "idle" | "busy" | "added" | "failed";
type Shown = AddState | "soldOut";

/** Every word the button can show. Each one is also drawn, unseen, in the same place, so the button keeps one width whatever it says. */
const SHOWN = ["idle", "busy", "added", "failed", "soldOut"] as const satisfies readonly Shown[];

/**
 * The Add button of one row: it shows when it is working (the label changes and a spinner turns), says Added with a
 * check for a moment and then goes back to rest. When the add fails it says "Try again" for a few seconds and a
 * polite message tells a screen reader. A press while it works is ignored without losing the keyboard's focus, which
 * a disabled button would drop. A product that cannot be bought gets a button that is off and says so. The button is
 * as wide as its longest word, in every state, so the columns of the row never move when it changes.
 */
export function RankedAddButton({ label, busyLabel, addedLabel, retryLabel, soldOutLabel, name, addedName, failedName, soldOut = false, onAdd, className }: RankedAddButtonProps) {
  const [state, setState] = useState<AddState>("idle");
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  async function press() {
    if (state === "busy" || state === "added" || soldOut) return;
    window.clearTimeout(timer.current);
    setState("busy");
    try {
      await onAdd?.();
      setState("added");
      timer.current = window.setTimeout(() => setState("idle"), 1800);
    } catch {
      setState("failed");
      timer.current = window.setTimeout(() => setState("idle"), 3000);
    }
  }

  const busy = state === "busy";
  const added = state === "added";
  const failed = state === "failed";
  const shown: Shown = soldOut ? "soldOut" : state;
  const words: Record<Shown, string> = { idle: label, busy: busyLabel, added: addedLabel, failed: retryLabel, soldOut: soldOutLabel };
  const glyphs: Record<Shown, ReactNode> = { idle: <IconPlus />, busy: <IconSpinner />, added: <IconCheck />, failed: <IconRefresh />, soldOut: null };

  return (
    <>
      <Button
        type="button"
        variant={added ? "secondary" : "outline"}
        size="sm"
        disabled={soldOut}
        aria-busy={busy || undefined}
        aria-disabled={busy || added || undefined}
        aria-label={added ? addedName : failed ? failedName : name}
        data-state={shown}
        onClick={() => void press()}
        className={cn(
          "relative z-10",
          // On a narrow list the button is a square with the icon and the word is left to screen readers, so the name of the product keeps its room. A product that cannot be bought keeps its words.
          !soldOut && "@max-md:w-8 @max-md:px-0",
          (busy || added) && "pointer-events-none",
          failed && "border-destructive/40 text-destructive hover:border-destructive/60 hover:bg-destructive/5 hover:text-destructive",
          className,
        )}
      >
        <span className="grid justify-items-center">
          {SHOWN.map((key) => {
            const seen = key === shown;
            return (
              <span key={key} aria-hidden={seen ? undefined : "true"} className={cn("col-start-1 row-start-1 inline-flex items-center gap-2", !seen && "invisible @max-md:hidden")}>
                {key === "soldOut" ? null : seen ? glyphs[key] : <span className="size-3.5 shrink-0" />}
                <span className={cn(seen && key !== "soldOut" && "@max-md:sr-only")}>{words[key]}</span>
              </span>
            );
          })}
        </span>
      </Button>
      <span role="status" className="sr-only">
        {failed ? failedName : null}
      </span>
    </>
  );
}

/** A product's picture. */
export interface RankedProductImage {
  /** The picture: a URL or a data URI. */
  src: string;
  /** What the picture shows. Leave it empty when the name beside it says it all, which is usual in a list. */
  alt?: string;
  /** The picture's width in pixels, so the page does not jump while it loads. */
  width?: number;
  /** The picture's height in pixels. */
  height?: number;
}

/** How a product moved since the last period: it is new, it went up or down some places, or it stayed. */
export type RankedMovement = { kind: "new" } | { kind: "same" } | { kind: "up" | "down"; by: number };

/** One product in the list. Its rank is its place in the array. */
export interface RankedProduct {
  /** Identity of the product in your shop: it is what the row is keyed on. */
  id: string;
  /** What it is called. */
  name: string;
  /** The product page. The whole row is this link. */
  href: string;
  /** A line under the name: the material, the size, the colour. */
  subtitle?: string;
  /** The price, in minor units: 8900 is 89.00. */
  price: number;
  /** What it cost before, in minor units, for a product on sale. It is written struck through. */
  compareAtPrice?: number;
  /** The product's picture. Without one the row shows a plain placeholder. */
  image?: RankedProductImage;
  /** The line of proof, already written the way you want it: "1,240 sold this week". */
  proof?: string;
  /** The average rating, from 0 to 5. Shown with a star beside, or under, the proof. */
  rating?: number;
  /** How many ratings it rests on. */
  ratingCount?: number;
  /** How the product moved since the last period: new, up or down some places, or steady. It is written as a word and, for a direction, an arrow. */
  movement?: RankedMovement;
  /** False for a product that cannot be bought now: it keeps its place, its Add button says so and is off. */
  available?: boolean;
}

/** One period the list can show: a week, a month, all time. */
export interface RankedPeriod {
  /** What `period` and `onPeriodChange` carry: "week". */
  value: string;
  /** What the control says: "This week". */
  label: string;
}

export const DEFAULT_PERIODS: readonly RankedPeriod[] = [
  { value: "week", label: "This week" },
  { value: "month", label: "This month" },
  { value: "all", label: "All time" },
];

export interface RankedProductListLabels {
  /** The heading when you gave none. */
  title?: string;
  /** The line under it. */
  description?: string;
  /** What a screen reader hears for the period control. */
  period?: string;
  /** What a screen reader hears for the list. `{period}`. */
  list?: string;
  /** What a screen reader hears before a name. `{rank}`. */
  rank?: string;
  /** The movement words. `{count}` places. */
  movementNew?: string;
  movementUp?: string;
  movementDown?: string;
  movementSame?: string;
  /** Before a price that was lowered, for a screen reader. */
  was?: string;
  /** The button on a row. */
  add?: string;
  /** What a screen reader hears on it. `{name}`. */
  addName?: string;
  /** The button while it works, and once the product is in the bag. */
  adding?: string;
  added?: string;
  /** What a screen reader hears on it once the product is in the bag. `{name}`. */
  addedName?: string;
  /** The button of a product that cannot be bought. */
  soldOut?: string;
  /** What a screen reader hears on that button: it holds the visible words, so the name says the product is sold out. `{name}`. */
  soldOutName?: string;
  /** The button for a moment after an add that failed. */
  retry?: string;
  /** What a screen reader hears on it, and the polite message when the add fails. It holds the visible words. `{name}`. */
  failedName?: string;
  /** What a screen reader hears for a rating. `{rating}` out of five, `{count}` ratings. */
  ratingName?: string;
  /** The polite status when the period changes. `{period}` and `{count}` products. */
  status?: string;
  statusOne?: string;
  /** The list when there is nothing in it. */
  empty?: string;
}

export const WORDS = {
  title: "Best sellers",
  description: "What people buy most, from the first place down.",
  period: "Period",
  list: "Best sellers, {period}",
  rank: "Number {rank}",
  movementNew: "New",
  movementUp: "Up {count}",
  movementDown: "Down {count}",
  movementSame: "Steady",
  was: "was",
  add: "Add",
  addName: "Add {name} to your bag",
  adding: "Adding",
  added: "Added",
  addedName: "{name} is in your bag",
  soldOut: "Sold out",
  soldOutName: "{name} is sold out",
  retry: "Try again",
  failedName: "{name} could not be added. Try again.",
  ratingName: "Rated {rating} out of 5 from {count} ratings",
  status: "Showing the best sellers for {period}: {count} products.",
  statusOne: "Showing the best seller for {period}: 1 product.",
  empty: "Nothing has sold in this period yet.",
} satisfies Required<RankedProductListLabels>;

export const fill = (template: string, values: Record<string, string>): string => template.replace(/\{(\w+)\}/g, (_, key: string) => values[key] ?? "");

/** The words of a movement and whether it points up, down or nowhere. `by` is rounded to whole places and must be at least one, or the movement is a plain "steady". */
export function movementOf(movement: RankedMovement | undefined, numbers: Intl.NumberFormat, words: { movementNew: string; movementUp: string; movementDown: string; movementSame: string }): { text: string; kind: "new" | "up" | "down" | "same" } | null {
  if (!movement) return null;
  if (movement.kind === "new") return { text: words.movementNew, kind: "new" };
  if (movement.kind === "same") return { text: words.movementSame, kind: "same" };
  const places = Math.round(movement.by);
  if (!Number.isFinite(places) || places < 1) return { text: words.movementSame, kind: "same" };
  return { text: fill(movement.kind === "up" ? words.movementUp : words.movementDown, { count: numbers.format(places) }), kind: movement.kind };
}
